shellCommands.command:
mkdir -p /tmp/ssr-check && cat > /tmp/ssr-check/entry.tsx <<'EOF'
import React from 'react';
import { renderToString } from 'react-dom/server';
import { ThemeProvider } from '@gravity-ui/uikit';
import { App } from '/home/sandbox/workspace/src/App';

const html = renderToString(
  <ThemeProvider theme="light">
    <App />
  </ThemeProvider>,
);
console.log(html.length, 'chars rendered');
console.log('has calendar grid:', /role="grid"|gridcell/.test(html));
console.log('has empty-state text:', html.includes('No date selected'));
console.log('has heading:', html.includes('Select a date'));
EOF
timeout 120 node node_modules/esbuild/bin/esbuild /tmp/ssr-check/entry.tsx --bundle --platform=node --format=esm --jsx=automatic --loader:.css=empty --outfile=/tmp/ssr-check/out.mjs --log-level=warning && timeout 60 node /tmp/ssr-check/out.mjs

cat > /tmp/ssr-check/entry2.tsx <<'EOF'
import { dateTime } from '@gravity-ui/date-utils';
const d = dateTime({ input: new Date(2026, 10, 6) });
console.log('formatted:', d.format('LL'));
EOF
sed "s#/tmp/ssr-check/entry.tsx#/tmp/ssr-check/entry2.tsx#; s#/tmp/ssr-check/out.cjs#/tmp/ssr-check/out2.cjs#" /tmp/ssr-check/build.mjs > /tmp/ssr-check/build2.mjs && timeout 120 node /tmp/ssr-check/build2.mjs && timeout 60 node /tmp/ssr-check/out2.cjs
